      h6: string;
      /** Subtitle: a short line under a heading. */
      subtitle: string;
      /** Body text: paragraphs and input values. The default text style. */
      body: string;
      /** Small text: secondary copy and compact controls. */
      small: string;
      /** A short uppercase label above a heading. */
